UPDATE KEPQTDT A		/*updateAgrmntKEPQTDT*/	
    SET BUYER_ITEM_NO = #{REG_ITEM_NO}	
  WHERE A.BUYER = #{BUYER}		
    AND A.QUOTATION_NO = #{QUOTATION_NO}	
    AND A.QUOTATION_SEQ = #{QUOTATION_SEQ}	
    AND A.REVISION = #{REVISION}


				UPDATE ICOMCQDT	A	/*updateAgrmntICOMCQDT*/	
				    SET A.TARGET_PRICE=#{ATOB_UNIT_PRICE}	
				 	   , A.UNIT_PRICE=#{ATOB_UNIT_PRICE}
				 	   , A.BUYER_ITEM_NO=CASE WHEN #{PRODUCT_CLOSE_FLAG} = 'S' OR #{PRODUCT_CLOSE_FLAG} = 'G'
		 	   											THEN #{REG_ITEM_NO}
				 	   									ELSE A.BUYER_ITEM_NO 
		 	   										END	
				 	   , A.AGENT = (CASE WHEN #{PROCESS_TYPE} = '1' OR #{PROCESS_TYPE} = '3' THEN #{WAREHOUSE_CODE} 
				 	   						   WHEN #{PROCESS_TYPE} = '0' OR #{PROCESS_TYPE} = '2' THEN #{AGENT}
				 	   			       END)						 	   
				 	   , A.PREV_DEAL_PRICE=#{BUYER_TARGET_PRICE}
				 	   , A.LIST_PRICE=#{STOA_LIST_PRICE}
				 	   , A.DESCRIPTION =DECODE(#{PRODUCT_CLOSE_FLAG},'S',#{DESCRIPTION},A.DESCRIPTION)
				 	   , A.SPECIFICATION =DECODE(#{PRODUCT_CLOSE_FLAG},'S',#{SPECIFICATION},A.SPECIFICATION)
				 	   , A.MAKER_NAME =DECODE(#{PRODUCT_CLOSE_FLAG},'S',#{MAKER_NAME},A.MAKER_NAME)
				 	   , A.UNIT_MEASURE = DECODE(#{PRODUCT_CLOSE_FLAG},'S',#{UNIT_MEASURE},A.UNIT_MEASURE)
				 	   , A.ORIGIN_CODE = DECODE(#{PRODUCT_CLOSE_FLAG},'S',#{ORIGIN_CODE},A.ORIGIN_CODE)				 	   
				 	   , A.IMPORT_FLAG=NVL(#{IMPORT_FLAG},'N')
				 	   , A.CHANGE_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD')
				 	   , A.CHANGE_TIME=TO_CHAR(SYSDATE, 'HH24MISS')
				 	   , A.STATUS='R'
				 	   , A.SELL_CLOSE_DATE=#{SELL_CLOSE_DATE}	
				 	   , A.BUY_CLOSE_DATE=#{BUY_CLOSE_DATE}
				 	   , A.MIN_ORDER_QTY = F_HST_ICOMCQDT(A.BUYER, A.CONTRACT_NO, A.CONTRACT_SEQ, 'MIN_ORDER_QTY', #{MIN_ORDER_QTY}, #{USR_ID})
				 	   , A.PUR_UNIT_QTY = F_HST_ICOMCQDT(A.BUYER, A.CONTRACT_NO, A.CONTRACT_SEQ, 'PUR_UNIT_QTY', #{PUR_UNIT_QTY}, #{USR_ID})
				  WHERE A.BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS IN ('C','R'))
				  	AND A.BUYER_ITEM_NO = #{BUYER_ITEM_NO}
				  	AND A.CONTRACT_NO = #{CONTRACT_NO}



					AND A.BELOW_COMORG_CODE IN (SELECT BL.COMORG_CODE
		                                                          FROM BYCAORGL BL, ICOMCMPY CP
		                                                         WHERE BL.P_COMORG_CODE  IN (SELECT P_COMORG_CODE
		                                                                                                     FROM BYCAORGL 
		                                                                                                     WHERE COMORG_CODE =  #{BUYER})
		                                                            AND BL.COMORG_CODE = CP.COM_CODE
		                                                            AND CP.STATUS IN ('C','R') )




                     AND A.BELOW_COMORG_CODE = #{BELOW_COMORG_CODE}


	UPDATE ICOMCQEP   /*updateAgrmntICOMCQEP*/			
 	   SET BUYER_ITEM_NO=#{REG_ITEM_NO}	
 	 WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS IN ('C','R'))
 	 	AND BUYER_ITEM_NO = #{REG_ITEM_NO}

INSERT INTO ICOMCQEP ( /*insertAgrmntICOMCQEP*/ BUYER, CONTRACT_NO, CONTRACT_SEQ, PRICE_SEQ, STATUS, ADD_DATE, ADD_TIME, CHANGE_DATE, CHANGE_TIME, ADD_USER_ID, BUYER_ITEM_NO, FROM_DATE, TO_DATE, FROM_QTY, TO_QTY, UNIT_PRICE, DETAIL_TERM, DETAIL_TERM_QTY, TAX_PRICE, LIST_PRICE, AGENT, SELL_CLOSE_DATE, BUY_CLOSE_DATE ) ( SELECT NVL(B.BUYER, ' '), NVL(B.CONTRACT_NO, ' '), NVL(B.CONTRACT_SEQ, ' '), NVL((SELECT NVL(MAX(C.PRICE_SEQ)+1,1) FROM ICOMCQEP C WHERE C.BUYER = B.BUYER AND C.CONTRACT_NO = B.CONTRACT_NO AND C.CONTRACT_SEQ= B.CONTRACT_SEQ),1) AS PRICE_SEQ, 'C', TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE, 'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE, 'HH24MISS'), NVL(#{USR_ID}, ' '), #{REG_ITEM_NO}, NVL(B.FROM_DATE, ' '), NVL(B.TO_DATE, ' '), 1 AS FROM_QTY, 99999999 AS TO_QTY, NVL(B.UNIT_PRICE, 0), NULL AS DETAIL_TERM, NULL AS DETAIL_TERM_QTY, NULL AS TAX_PRICE, NVL(B.LIST_PRICE, 0), #{AGENT}, #{SELL_CLOSE_DATE}, #{BUY_CLOSE_DATE} FROM ICOMCQDT B WHERE B.BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS IN ('C','R')) AND B.BUYER_ITEM_NO = #{REG_ITEM_NO} AND B.CONTRACT_NO = #{CONTRACT_NO}
AND B.BELOW_COMORG_CODE IN (SELECT BL.COMORG_CODE FROM BYCAORGL BL, ICOMCMPY CP WHERE BL.P_COMORG_CODE IN (SELECT P_COMORG_CODE FROM BYCAORGL WHERE COMORG_CODE = #{BUYER}) AND BL.COMORG_CODE = CP.COM_CODE AND CP.STATUS IN ('C','R') )
AND B.BELOW_COMORG_CODE = #{BELOW_COMORG_CODE}
)


UPDATE KEPRQDT		/*updateAgrmntKEPRQDT*/				
    SET REG_ITEM_NO=#{REG_ITEM_NO},				
 	   BUYER_ITEM_NO=#{REG_ITEM_NO},				
 	   RECV_FLAG='CM'				
  WHERE BUYER=#{BUYER}					
    AND QUOTATION_NO=#{QUOTATION_NO}			
    AND QUOTATION_SEQ=#{QUOTATION_SEQ}				
    AND REVISION=#{REVISION}					
    AND STATUS IN ('C','R')


UPDATE KEPRQDT			/*updateAgrmntKEPRQDT2*/						
    SET REG_ITEM_NO=#{REG_ITEM_NO},							
 	   RECV_FLAG='CM',							
 	   CONFIRM_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD'),
 	   CONFIRM_TIME=TO_CHAR(SYSDATE, 'HH24MISS'),
 	   CONFIRM_USER_ID=#{USR_ID},						
 	   BUYER_ITEM_NO=#{REG_ITEM_NO}							
  WHERE BUYER=#{BUYER}									
    AND QUOTATION_NO=#{QUOTATION_NO}							
    AND QUOTATION_SEQ=#{QUOTATION_SEQ}							
    AND REVISION=#{REVISION}								
    AND STATUS IN ('C','R')


UPDATE KEPRQDT A   /*updateAgrmntKEPRQDT3*/
    SET A.BUYER_ITEM_NO=#{REG_ITEM_NO},
 	   A.REG_ITEM_NO=#{REG_ITEM_NO}
  WHERE A.BUYER=#{BUYER}		
    AND A.CONTRACT_NO=#{CONTRACT_NO}	
    AND A.CONTRACT_SEQ=#{CONTRACT_SEQ}

